formSchemaJson:
{
  "fields": [
    {
      "key": "team.objective",
      "label": "Team objective",
      "widget": "callout",
      "dataType": "string",
      "colSpan": 12,
      "constraints": {
        "required": true,
        "minLength": 20,
        "maxLength": 260
      }
    },
    {
      "key": "team.selectionMethod",
      "label": "Selection method",
      "widget": "status",
      "dataType": "string",
      "colSpan": 4,
      "constraints": {
        "required": true,
        "enum": [
          "Current case team",
          "Precedent recommendation",
          "Hybrid",
          "Roles only - assignment required"
        ]
      }
    },
    {
      "key": "team.problemCapabilities",
      "label": "Capabilities required by this problem",
      "widget": "tag-selector",
      "dataType": "array",
      "colSpan": 8,
      "constraints": {
        "required": true,
        "minItems": 1
      },
      "items": {
        "type": "string"
      }
    },
    {
      "key": "team.selectionRationale",
      "label": "How the team was selected",
      "widget": "markdown",
      "dataType": "string",
      "colSpan": 12,
      "constraints": {
        "required": true,
        "minLength": 60,
        "maxLength": 1600
      }
    },
    {
      "key": "team.roster",
      "label": "AI suggest",
      "widget": "ai-suggest",
      "dataType": "array",
      "colSpan": 12,
      "constraints": {
        "required": true,
        "minItems": 1
      },
      "items": {
        "type": "object",
        "properties": {
          "name": {
            "type": "string",
            "maxLength": 120,
            "description": "ONLY the person name, or \"Unassigned\". No role, no reasoning."
          },
          "organizationalRole": {
            "type": "string",
            "maxLength": 120,
            "description": "ONLY their job title in the organisation, e.g. \"Quality Engineer\"."
          },
          "assigned8DRole": {
            "type": "string",
            "maxLength": 60,
            "description": "ONLY their role in THIS 8D, e.g. \"Team Leader\" or \"Team Member\"."
          },
          "caseResponsibility": {
            "type": "string",
            "maxLength": 200,
            "description": "What this person is accountable for here. Never a job title."
          },
          "selectionReason": {
            "type": "string",
            "maxLength": 220,
            "description": "Why this person, in one line. Do not repeat the name or the role."
          },
          "servedOnCount": {
            "type": "integer",
            "description": "How many qualifying precedent cases this person served on. Rank the roster by this value, descending."
          },
          "sourceType": {
            "type": "string",
            "enum": [
              "current_case",
              "precedent",
              "unassigned"
            ]
          },
          "sourcePath": {
            "type": "string",
            "maxLength": 80,
            "description": "ONLY the resolvable path: team.leader, team.members#N, precedents#N.team#M, or team.gaps."
          },
          "sourceCase": {
            "type": "string",
            "maxLength": 60,
            "description": "ONLY the precedent notification id, when the person came from a precedent."
          }
        },
        "required": [
          "name",
          "organizationalRole",
          "assigned8DRole",
          "caseResponsibility",
          "selectionReason",
          "sourceType",
          "sourcePath"
        ]
      }
    },
    {
      "key": "team.assignedRoster",
      "label": "Decision table",
      "widget": "decision-table",
      "dataType": "array",
      "colSpan": 12,
      "constraints": {},
      "xSource": "manual_input",
      "description": "Filled in by the quality engineer on the report screen. The AI never writes this.",
      "items": {
        "type": "object",
        "properties": {
          "partnerId": {
            "type": "string"
          },
          "partnerName": {
            "type": "string"
          },
          "functionTitle": {
            "type": "string"
          },
          "partnerRole": {
            "type": "string",
            "enum": [
              "8D Team Leader",
              "8D Team Member"
            ]
          }
        }
      }
    },
    {
      "key": "team.readinessStatus",
      "label": "Team readiness",
      "widget": "status",
      "dataType": "string",
      "colSpan": 3,
      "constraints": {
        "required": true,
        "enum": [
          "Ready",
          "Partial",
          "Needs assignment"
        ]
      }
    },
    {
      "key": "team.readinessRationale",
      "label": "Readiness assessment",
      "widget": "markdown",
      "dataType": "string",
      "colSpan": 9,
      "constraints": {
        "required": true,
        "minLength": 30,
        "maxLength": 500
      }
    },
    {
      "key": "team.uncoveredCapabilities",
      "label": "Uncovered capabilities",
      "widget": "warning-list",
      "dataType": "array",
      "colSpan": 6,
      "constraints": {},
      "items": {
        "type": "string"
      }
    },
    {
      "key": "team.sourceSummary",
      "label": "Where the team recommendation came from",
      "widget": "markdown",
      "dataType": "string",
      "colSpan": 6,
      "constraints": {
        "required": true,
        "minLength": 30,
        "maxLength": 500
      }
    },
    {
      "key": "team.suggestionStatus",
      "label": "Suggestion status",
      "widget": "callout",
      "dataType": "string",
      "colSpan": 12,
      "constraints": {}
    },
    {
      "key": "sources",
      "label": "Source records",
      "widget": "evidence-list",
      "dataType": "array",
      "colSpan": 12,
      "constraints": {
        "pattern": "^(team\\.|precedents#)"
      },
      "items": {
        "type": "string"
      }
    }
  ],
  "groups": [
    {
      "id": "d1-decision-table",
      "label": "Decision Table",
      "fieldKeys": [
        "team.assignedRoster",
        "team.suggestionStatus"
      ],
      "width": "100",
      "columns": 12,
      "order": 10
    }
  ]
}

{
  "fields": [
    {
      "key": "problem.complaintReference",
      "label": "Complaint reference",
      "widget": "complaint-reference",
      "dataType": "string",
      "colSpan": 12,
      "constraints": {},
      "xSource": "sap_qm",
      "description": "Read from the SAP QM customer reference on the case. The AI never writes this."
    },
    {
      "key": "problem.statement",
      "label": "Problem statement",
      "widget": "problem-statement",
      "dataType": "string",
      "colSpan": 12,
      "constraints": {
        "required": true,
        "minLength": 30,
        "maxLength": 600
      }
    },
    {
      "key": "problem.statementOverride",
      "label": "Problem statement (edited)",
      "widget": "text",
      "dataType": "string",
      "colSpan": 12,
      "constraints": {},
      "xSource": "manual_input",
      "description": "Edited by the quality engineer on the report screen. The AI never writes this."
    },
    {
      "key": "problem.what",
      "label": "What",
      "widget": "w2h-cell",
      "dataType": "string",
      "colSpan": 4,
      "constraints": {
        "required": true
      }
    },
    {
      "key": "problem.where",
      "label": "Where",
      "widget": "w2h-cell",
      "dataType": "string",
      "colSpan": 4,
      "constraints": {
        "required": true
      }
    },
    {
      "key": "problem.when",
      "label": "When",
      "widget": "w2h-cell",
      "dataType": "string",
      "colSpan": 4,
      "constraints": {}
    },
    {
      "key": "problem.who",
      "label": "Who",
      "widget": "w2h-cell",
      "dataType": "string",
      "colSpan": 4,
      "constraints": {}
    },
    {
      "key": "problem.how",
      "label": "How",
      "widget": "w2h-cell",
      "dataType": "string",
      "colSpan": 4,
      "constraints": {}
    },
    {
      "key": "problem.extent",
      "label": "How Many",
      "widget": "w2h-cell",
      "dataType": "string",
      "colSpan": 4,
      "constraints": {
        "required": true
      }
    },
    {
      "key": "problem.impact",
      "label": "Business / customer impact",
      "widget": "text",
      "dataType": "string",
      "colSpan": 12,
      "constraints": {}
    },
    {
      "key": "problem.is",
      "label": "Is",
      "widget": "is-box",
      "dataType": "array",
      "colSpan": 6,
      "constraints": {},
      "items": {
        "type": "string"
      }
    },
    {
      "key": "problem.isNot",
      "label": "Is not",
      "widget": "isnot-box",
      "dataType": "array",
      "colSpan": 6,
      "constraints": {},
      "items": {
        "type": "string"
      }
    },
    {
      "key": "problem.isIsNotStatus",
      "label": "Is / Is-Not status",
      "widget": "callout",
      "dataType": "string",
      "colSpan": 12,
      "constraints": {}
    },
    {
      "key": "problem.isIsNotBasis",
      "label": "Is / Is-Not basis",
      "widget": "markdown",
      "dataType": "string",
      "colSpan": 12,
      "constraints": {}
    },
    {
      "key": "problem.measuredEvidence",
      "label": "Measured evidence",
      "widget": "table",
      "dataType": "array",
      "colSpan": 12,
      "constraints": {},
      "items": {
        "type": "object",
        "properties": {
          "characteristic": {
            "type": "string",
            "maxLength": 120,
            "description": "ONLY the characteristic name, e.g. \"Burr height\". No value, no verdict."
          },
          "measured": {
            "type": "string",
            "maxLength": 60,
            "description": "ONLY the measured value with its unit, e.g. \"0.32 mm\"."
          },
          "specification": {
            "type": "string",
            "maxLength": 60,
            "description": "ONLY the specification limit with its unit, e.g. \"max 0.10 mm\"."
          },
          "assessment": {
            "type": "string",
            "maxLength": 120,
            "description": "ONLY the verdict, e.g. \"Out of tolerance\" or \"Within spec\". No restatement of the numbers."
          }
        }
      }
    },
    {
      "key": "problem.gaps",
      "label": "Missing facts",
      "widget": "warning-list",
      "dataType": "array",
      "colSpan": 12,
      "constraints": {},
      "items": {
        "type": "string"
      }
    },
    {
      "key": "sources",
      "label": "Evidence and traceability",
      "widget": "evidence-list",
      "dataType": "array",
      "colSpan": 12,
      "constraints": {},
      "items": {
        "type": "string"
      }
    }
  ],
  "groups": [
    {
      "id": "d2-ai-result",
      "label": "AI-generated problem description",
      "fieldKeys": [
        "problem.complaintReference",
        "problem.statement",
        "problem.what",
        "problem.where",
        "problem.when",
        "problem.who",
        "problem.how",
        "problem.extent",
        "problem.is",
        "problem.isNot",
        "problem.isIsNotStatus",
        "problem.isIsNotBasis"
      ],
      "width": "100",
      "columns": 12,
      "order": 10
    }
  ]
}

{
  "fields": [
    {
      "key": "containment.actions",
      "label": "Containment actions",
      "widget": "action-cards",
      "dataType": "array",
      "colSpan": 12,
      "constraints": {
        "required": true,
        "minItems": 1
      },
      "items": {
        "type": "object",
        "properties": {
          "action": {
            "type": "string",
            "description": "Short concise action description without boilerplate prefix. Start with the imperative verb naming the PRIMARY work, e.g. \"Quarantine 85 housings at the outgoing dock\"."
          },
          "owner": {
            "type": "string",
            "maxLength": 120,
            "description": "The team member from D1 (team.roster or team.leader/members) assigned to this containment action, selected by matching their role/responsibility to the work required. E.g. \"Karl Wagner\" or \"DungTruonghyhy\"."
          },
          "status": {
            "type": "string",
            "enum": [
              "Planned",
              "In Process",
              "Done",
              "Verified"
            ]
          }
        }
      }
    },
    {
      "key": "containment.gaps",
      "label": "Open containment gaps",
      "widget": "warning-list",
      "dataType": "array",
      "colSpan": 12,
      "constraints": {},
      "items": {
        "type": "string"
      }
    },
    {
      "key": "sources",
      "label": "Evidence and traceability",
      "widget": "evidence-list",
      "dataType": "array",
      "colSpan": 12,
      "constraints": {},
      "items": {
        "type": "string"
      }
    }
  ],
  "groups": [
    {
      "id": "d3-ai-result",
      "label": "Containment plan",
      "fieldKeys": [
        "containment.actions",
        "containment.gaps",
        "sources"
      ],
      "width": "100",
      "columns": 12,
      "order": 10
    }
  ]
}

{
  "fields": [
    {
      "key": "rootCause.statement",
      "label": "Root cause",
      "widget": "ai-draft",
      "dataType": "string",
      "colSpan": 12,
      "constraints": {
        "required": true,
        "minLength": 10,
        "maxLength": 320
      }
    },
    {
      "key": "rootCause.ishikawaBoard",
      "label": "Ishikawa",
      "widget": "ishikawa-grid",
      "dataType": "array",
      "colSpan": 12,
      "constraints": {
        "required": true,
        "minItems": 6
      },
      "description": "Always one row per 6M category with a concise 1-sentence verdict. Copy a recorded assessment verbatim with source=recorded; for a category with no recorded entry propose a brief verdict from evidence with source=proposed, or write \"not assessed\". Never write audit plans or long essays in cells.",
      "items": {
        "type": "object",
        "properties": {
          "category": {
            "type": "string",
            "enum": [
              "Man",
              "Machine",
              "Method",
              "Material",
              "Measurement",
              "Environment"
            ]
          },
          "finding": {
            "type": "string",
            "maxLength": 220,
            "description": "The concise VERDICT for this branch, e.g. clamp pad worn 0.2 mm, or gauge R&R 8%, or not assessed. Never a list of evidence to gather - that goes in evidenceGaps once. Never the category name."
          },
          "isRootCause": {
            "type": "boolean",
            "description": "True for at most ONE branch in the whole board."
          },
          "source": {
            "type": "string",
            "enum": [
              "recorded",
              "proposed"
            ]
          }
        },
        "required": [
          "category",
          "finding",
          "isRootCause",
          "source"
        ]
      }
    },
    {
      "key": "rootCause.fiveWhy",
      "label": "5-Why chain",
      "widget": "why-chain",
      "dataType": "array",
      "colSpan": 12,
      "constraints": {
        "required": true,
        "minItems": 1
      },
      "items": {
        "type": "object",
        "properties": {
          "step": {
            "type": "integer",
            "description": "Position in the chain, starting at 1."
          },
          "why": {
            "type": "string",
            "maxLength": 140,
            "description": "The question only, ending in a question mark. Keep it short and crisp."
          },
          "answer": {
            "type": "string",
            "maxLength": 200,
            "description": "The answer only: 1 concise direct sentence naming the cause. Never repeat the question, never list audit procedures or evidence still to be gathered."
          },
          "evidence": {
            "type": "string",
            "maxLength": 200,
            "description": "The CaseContext path or measurement backing the answer. Concise citation only."
          }
        },
        "required": [
          "step",
          "why",
          "answer",
          "evidence"
        ]
      }
    },
    {
      "key": "rootCause.evidenceGaps",
      "label": "Evidence gaps",
      "widget": "warning-list",
      "dataType": "array",
      "colSpan": 12,
      "constraints": {},
      "items": {
        "type": "string"
      }
    },
    {
      "key": "sources",
      "label": "Evidence and traceability",
      "widget": "evidence-list",
      "dataType": "array",
      "colSpan": 12,
      "constraints": {},
      "items": {
        "type": "string"
      }
    }
  ],
  "groups": [
    {
      "id": "d4-ai-result",
      "label": "Root cause analysis",
      "fieldKeys": [
        "rootCause.statement",
        "rootCause.ishikawaBoard",
        "rootCause.fiveWhy",
        "rootCause.evidenceGaps",
        "sources"
      ],
      "width": "100",
      "columns": 12,
      "order": 10
    }
  ]
}

{
  "fields": [
    {
      "key": "corrective.actions",
      "label": "Permanent corrective actions",
      "widget": "action-cards",
      "dataType": "array",
      "colSpan": 12,
      "constraints": {
        "required": true,
        "minItems": 1
      },
      "items": {
        "type": "object",
        "properties": {
          "action": {
            "type": "string",
            "maxLength": 240,
            "description": "The action and its trigger, starting with the imperative verb that names the PRIMARY work. No owner, no status, no rationale - those are separate fields."
          },
          "owner": {
            "type": "string",
            "maxLength": 120,
            "description": "The team member from D1 (team.roster or team.leader/members) assigned to this corrective action, selected by matching their role/responsibility to the root cause fix. E.g. \"Karl Wagner\" or \"Minh Dinh\"."
          },
          "status": {
            "type": "string",
            "maxLength": 40,
            "description": "ONLY the current status, one or two words, e.g. \"Planned\", \"In progress\", \"Done\"."
          },
          "origin": {
            "type": "string",
            "maxLength": 60,
            "description": "ONLY where it came from: \"recorded\" for an action already in the case, or \"precedents#N\" for a proposal."
          },
          "protection": {
            "type": "string",
            "maxLength": 200,
            "description": "One line."
          }
        }
      }
    },
    {
      "key": "sources",
      "label": "Evidence and traceability",
      "widget": "evidence-list",
      "dataType": "array",
      "colSpan": 12,
      "constraints": {},
      "items": {
        "type": "string"
      }
    }
  ],
  "groups": [
    {
      "id": "d5-ai-result",
      "label": "AI-generated corrective plan",
      "fieldKeys": [
        "corrective.actions"
      ],
      "width": "100",
      "columns": 12,
      "order": 10
    }
  ]
}

{
  "fields": [
    {
      "key": "verification.objective",
      "label": "Verification objective",
      "widget": "callout",
      "dataType": "string",
      "colSpan": 12,
      "constraints": {
        "required": true,
        "maxLength": 260
      }
    },
    {
      "key": "verification.plan",
      "label": "Verification plan",
      "widget": "table",
      "dataType": "array",
      "colSpan": 12,
      "constraints": {
        "required": true,
        "minItems": 1
      },
      "items": {
        "type": "object",
        "properties": {
          "measure": {
            "type": "string",
            "maxLength": 200,
            "description": "One line."
          },
          "sampleSize": {
            "type": "string",
            "maxLength": 80,
            "description": "ONLY the sample size, e.g. \"30 parts per shift\"."
          },
          "period": {
            "type": "string",
            "maxLength": 60,
            "description": "ONLY the period over which it runs, e.g. \"4 weeks\"."
          },
          "acceptanceCriterion": {
            "type": "string",
            "maxLength": 220,
            "description": "The pass/fail threshold with its number, anchored to a real specification value."
          },
          "signOff": {
            "type": "string",
            "maxLength": 120,
            "description": "ONLY the role that signs it off."
          }
        }
      }
    },
    {
      "key": "verification.evidenceStatus",
      "label": "Evidence status",
      "widget": "status",
      "dataType": "string",
      "colSpan": 4,
      "constraints": {
        "required": true,
        "enum": [
          "No evidence yet",
          "Partially verified",
          "Verified"
        ]
      }
    },
    {
      "key": "sources",
      "label": "Evidence and traceability",
      "widget": "evidence-list",
      "dataType": "array",
      "colSpan": 12,
      "constraints": {},
      "items": {
        "type": "string"
      }
    }
  ],
  "groups": [
    {
      "id": "d6-ai-result",
      "label": "AI-generated verification plan",
      "fieldKeys": [
        "verification.objective",
        "verification.plan"
      ],
      "width": "100",
      "columns": 12,
      "order": 10
    }
  ]
}

{
  "fields": [
    {
      "key": "preventive.actions",
      "label": "Preventive actions",
      "widget": "action-cards",
      "dataType": "array",
      "colSpan": 12,
      "constraints": {
        "required": true,
        "minItems": 1
      },
      "items": {
        "type": "object",
        "properties": {
          "action": {
            "type": "string",
            "maxLength": 240,
            "description": "The action and its trigger, starting with the imperative verb that names the PRIMARY work. No owner, no status, no rationale - those are separate fields."
          },
          "owner": {
            "type": "string",
            "maxLength": 120,
            "description": "The team member from D1 (team.roster or team.leader/members) assigned to this preventive action, selected by matching their role/responsibility to the systemic/FMEA fix. E.g. \"Minh Dinh\" or \"DungTruonghyhy\"."
          },
          "status": {
            "type": "string",
            "maxLength": 40,
            "description": "ONLY the current status, one or two words, e.g. \"Planned\", \"In progress\", \"Done\"."
          },
          "origin": {
            "type": "string",
            "maxLength": 60,
            "description": "ONLY where it came from: \"recorded\" for an action already in the case, or \"precedents#N\" for a proposal."
          },
          "protection": {
            "type": "string",
            "maxLength": 200,
            "description": "One line."
          }
        }
      }
    },
    {
      "key": "preventive.fmea",
      "label": "FMEA entry to update",
      "widget": "fmea-link",
      "dataType": "object",
      "colSpan": 12,
      "constraints": {},
      "properties": {
        "fmeaId": {
          "type": "string"
        },
        "description": {
          "type": "string"
        },
        "change": {
          "type": "string"
        },
        "currentRating": {
          "type": "string"
        },
        "proposedRating": {
          "type": "string"
        }
      }
    },
    {
      "key": "sources",
      "label": "Evidence and traceability",
      "widget": "evidence-list",
      "dataType": "array",
      "colSpan": 12,
      "constraints": {},
      "items": {
        "type": "string"
      }
    }
  ],
  "groups": [
    {
      "id": "d7-ai-result",
      "label": "AI-generated preventive plan",
      "fieldKeys": [
        "preventive.actions",
        "preventive.fmea"
      ],
      "width": "100",
      "columns": 12,
      "order": 10
    }
  ]
}

{
  "fields": [
    {
      "key": "closure.gate",
      "label": "Closure readiness",
      "widget": "closure-gate",
      "dataType": "object",
      "colSpan": 12,
      "constraints": {},
      "xSource": "manual_input",
      "description": "Computed from the review status of D1-D7. The AI never writes this.",
