      "items": {
        "type": "object",
        "properties": {
          "partnerId": {
            "type": "string"
          },
          "partnerName": {
            "type": "string"
          },
          "functionTitle": {
            "type": "string"
          },
          "partnerRole": {
            "type": "string",
            "enum": [
              "8D Team Leader",
              "8D Team Member"
            ]
          }
        }
      }
    },
