      "items": {
        "type": "object",
        "properties": {
          "partnerId": {
            "type": "string"
          },
          "partnerName": {
            "type": "string"
          },
          "functionTitle": {
            "type": "string"
          },
          "partnerRole": {
            "type": "string",
            "enum": [
              "8D Team Leader",
              "8D Team Member"
            ]
          }
        }
      }
    },
    {
      "key": "team.readinessStatus",
      "label": "Team readiness",
      "widget": "status",
      "dataType": "string",
      "colSpan": 3,
      "constraints": {
        "required": true,
        "enum": [
          "Ready",
          "Partial",
          "Needs assignment"
        ]
      }
    },
    {
      "key": "team.readinessRationale",
      "label": "Readiness assessment",
      "widget": "markdown",
      "dataType": "string",
      "colSpan": 9,
      "constraints": {
        "required": true,
        "minLength": 30,
        "maxLength": 500
      }
    },
    {
      "key": "team.uncoveredCapabilities",
      "label": "Uncovered capabilities",
      "widget": "warning-list",
      "dataType": "array",
      "colSpan": 6,
      "constraints": {},
      "items": {
        "type": "string"
      }
    },
    {
      "key": "team.sourceSummary",
