      "colSpan": 8,
      "constraints": {
        "required": true,
        "minItems": 1
      },
      "items": {
        "type": "string"
      }
    },
    {
      "key": "team.selectionRationale",
      "label": "How the team was selected",
      "widget": "markdown",
      "dataType": "string",
      "colSpan": 12,
      "constraints": {
        "required": true,
        "minLength": 60,
        "maxLength": 1600
      }
    },
    {
      "key": "team.roster",
      "label": "AI suggest",
      "widget": "ai-suggest",
      "dataType": "array",
      "colSpan": 12,
      "constraints": {
        "required": true,
        "minItems": 1
      },
      "items": {
        "type": "object",
        "properties": {
          "name": {
            "type": "string",
            "maxLength": 120,
            "description": "ONLY the person name, or \"Unassigned\". No role, no reasoning."
          },
          "organizationalRole": {
            "type": "string",
            "maxLength": 120,
            "description": "ONLY their job title in the organisation, e.g. \"Quality Engineer\"."
          },
          "assigned8DRole": {
            "type": "string",
            "maxLength": 60,
            "description": "ONLY their role in THIS 8D, e.g. \"Team Leader\" or \"Team Member\"."
          },
          "caseResponsibility": {
            "type": "string",
            "maxLength": 200,
            "description": "What this person is accountable for here. Never a job title."
          },
          "selectionReason": {
            "type": "string",
            "maxLength": 220,
            "description": "Why this person, in one line. Do not repeat the name or the role."
          },
          "servedOnCount": {
            "type": "integer",
            "description": "How many qualifying precedent cases this person served on. Rank the roster by this value, descending."
          },
          "sourceType": {
            "type": "string",
            "enum": [
              "current_case",
              "precedent",
              "unassigned"
            ]
          },
          "sourcePath": {
            "type": "string",
            "maxLength": 80,
            "description": "ONLY the resolvable path: team.leader, team.members#N, precedents#N.team#M, or team.gaps."
          },
          "sourceCase": {
            "type": "string",
            "maxLength": 60,
            "description": "ONLY the precedent notification id, when the person came from a precedent."
          }
        },
        "required": [
          "name",
          "organizationalRole",
          "assigned8DRole",
          "caseResponsibility",
          "selectionReason",
          "sourceType",
          "sourcePath"
        ]
      }
    },
