          "Ready",
          "Partial",
          "Needs assignment"
        ]
      }
    },
    {
      "key": "team.readinessRationale",
      "label": "Readiness assessment",
      "widget": "markdown",
      "dataType": "string",
      "colSpan": 9,
      "constraints": {
        "required": true,
        "minLength": 30,
        "maxLength": 500
      }
