      "constraints": {
        "required": true,
        "minItems": 1
      },
      "items": {
        "type": "object",
        "properties": {
          "action": {
            "type": "string",
            "maxLength": 240,
            "description": "The action and its trigger, starting with the imperative verb that names the PRIMARY work. No owner, no status, no rationale - those are separate fields."
          },
          "owner": {
            "type": "string",
            "maxLength": 120,
            "description": "The team member from D1 (team.roster or team.leader/members) assigned to this corrective action, selected by matching their role/responsibility to the root cause fix. E.g. \"Karl Wagner\" or \"Minh Dinh\"."
          },
          "status": {
            "type": "string",
            "maxLength": 40,
            "description": "ONLY the current status, one or two words, e.g. \"Planned\", \"In progress\", \"Done\"."
          },
          "origin": {
            "type": "string",
            "maxLength": 60,
            "description": "ONLY where it came from: \"recorded\" for an action already in the case, or \"precedents#N\" for a proposal."
          },
          "protection": {
            "type": "string",
            "maxLength": 200,
            "description": "One line."
          }
        }
      }
    },
    {
      "key": "sources",
      "label": "Evidence and traceability",
      "widget": "evidence-list",
      "dataType": "array",
      "colSpan": 12,
      "constraints": {},
      "items": {
        "type": "string"
      }
    }
  ],
  "groups": [
    {
      "id": "d5-ai-result",
      "label": "AI-generated corrective plan",
      "fieldKeys": [
        "corrective.actions"
      ],
      "width": "100",
      "columns": 12,
      "order": 10
    }
  ]
}

